#!/usr/bin/env python3
"""Publish the authoritative KB16 evidence index without touching original inputs."""
from pathlib import Path
import hashlib,json,shutil
ROOT=Path(__file__).resolve().parents[1]; E=ROOT/'evaluation/v7'; OUT=ROOT/'outputs/v7'
def read(p): return json.loads(Path(p).read_text(encoding='utf-8'))
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(p,x): Path(p).parent.mkdir(parents=True,exist_ok=True);Path(p).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def main():
 kb=ROOT/'skills/order-mapping/knowledge/procurement.json'; kbsha=sha(kb)
 v1=read(E/'kb16_final_audit_v5/report.json'); sem=read(E/'semantic_kb16_final/report.json'); fresh=read(E/'fresh_kb16_final_shared/report.json'); v2=read(E/'kb16_v2_final_bundled_audit_v6/report.json'); orig=read(E/'original_kb16_final/report.json'); hist=read(E/'kb16_final_history/replay_audit.json'); identity=read(E/'kb16_final_history_identity.json'); cand=read(E/'kb16_candidate_audit_final.json')
 before=read(E/'kb16_original_sha_before.json'); after=read(E/'kb16_original_sha_after.json'); original_equal=all(after.get(k)==v for k,v in before.items() if k.startswith('original/'))
 def compact(m): return {k:m.get(k) for k in ('events','input_events','automatic','automatic_correct','correct','A','A_percent','B','B_percent','C','C_percent','missing_outputs','unexpected_outputs','C_status','business_processing_rate') if k in m}
 validation={'schema_version':2,'node':'V7-8-KB16-final','status':'doing','verified':False,'reason':'A passes on automatic rows, but full B remains 48.1481% on KB16 and 94.4444% on the fresh lane; C and real-host acceptance are incomplete.','knowledge_version':16,'knowledge_sha256':kbsha,'denominators':{'all_chat_events':159,'aligned_chat_manual_events':155,'current_catalog_manual_sku_events':132,'stations':{'松北大道':53,'星月':42,'学院路':64},'v2_events_per_seed':32,'v2_total_events':96,'fresh_events':324,'fresh_normal_events':306,'semantic_events':84,'semantic_normal_events':72},'metrics':{'kb16_v1':{mode:compact(m) for mode,m in v1['mode_summaries'].items()},'semantic_kb16_final':{mode:{'full':compact(m['summary']),'normal':compact(m['normal'])} for mode,m in sem['mode_summaries'].items()},'fresh_kb16_final_shared':{'full':compact(fresh['full_denominator_summary']),'normal':compact(fresh['normal_subset'])},'kb16_v2_challenge':{mode:compact(m) for mode,m in v2['mode_summaries'].items()},'historical_original159':orig,'historical_random_replay':hist['metrics'],'historical_fixed_identity':identity['groups']},'candidate_audit':{'old_four_concepts':cand['old_four_concepts']['event_count'],'old_four_complete':sum(d['score']['candidate_set']=='complete' for d in cand['old_four_concepts']['details']),'fresh_six':cand['fresh_six']['event_count'],'fresh_details':cand['fresh_six']['details']},'finance':{'v1_all_modes_zero_errors':all(not r['finance_audit']['errors'] for r in v1['runs']),'fresh_error_counts':fresh['finance_error_counts'],'original_merge_errors':read(E/'original_kb16_final_combined_bundled/report.json')['finance_errors'],'original_merge_rows':read(E/'original_kb16_final_combined_bundled/report.json')['events']},'source_integrity':{'original_before':before,'original_after':after,'original_equal':original_equal,'catalog_sha256':sha(ROOT/'original/食堂食材基准价价格表10.12-10.18.xlsx')},'artifact_paths':{'v1_audit':'evaluation/v7/kb16_final_audit_v5','v1_authoritative_audit':'evaluation/v7/kb16_final_audit_v5','semantic':'evaluation/v7/semantic_kb16_final','fresh':'evaluation/v7/fresh_kb16_final_shared','v2_audit':'evaluation/v7/kb16_v2_final_bundled_audit_v6','original':'evaluation/v7/original_kb16_final','original_merge':'evaluation/v7/original_kb16_final_combined_bundled','history':'evaluation/v7/kb16_final_history','identity':'evaluation/v7/kb16_final_history_identity.json','candidate':'evaluation/v7/kb16_candidate_audit_final.json','comparison':'evaluation/v7/kb16逐项对比.xlsx','simulation':'evaluation/v7/kb16_final_simulation'},'limitations':['v2 8991使用与开发seed共享短语池，属于保留合成回归而非未见真实订单证明。','v2牛心管“切段”等预期存在目录证据不足，按业务设计应保留待核风险，不能为分数强行自动化。','C保持null/unknown：有限候选见证通过不等于语义全集候选完整。','历史人工实配量、替代、旧价和行号不进入运行端；固定身份仅是历史参照。','千问办公、WorkBuddy、真实新增客户订单、真实系统导入和正式财务入账未验证。']}
 write(E/'kb16_validation_result.json',validation)
 sim=E/'kb16_final_simulation'; sim.mkdir(exist_ok=True)
 write(sim/'manifest.json',{'schema_version':2,'node':'V7-8-KB16-final','knowledge_sha256':kbsha,'seeds':{'v1':[8801,8802,8891],'v2':[8901,8902,8991],'fresh':[7601,7602,7691],'semantic':[8701,8702,8791]},'event_counts':{'v1_per_seed':18,'v2_per_seed':32,'fresh_per_seed':108,'semantic_per_seed':28},'roles':{'v1':'已见/已消费回归','v2_8901_8902':'开发集','v2_8991':'首见保留但共享表达池','fresh':'目录迁移回归','semantic':'已见表达回归'},'runtime_contract':'实际聊天文本 -> CLI run-messages -> 订单/财务草稿 -> 独立评测读取 expected','expected_is_evaluation_only':True,'source_integrity':'八个original文件前后SHA一致','candidate_completeness':'C不宣称'})
 (sim/'README.md').write_text('# KB16 final simulation index\n\n本目录索引所有最终验证轨。运行端只接收普通聊天、公司配置和当前目录；expected、事件ID、来源和历史决策在冻结运行完成后才由审计端读取。v2保留集与开发集复用固定短语池，不能视为未来真实订单泛化证明。\n',encoding='utf-8')
 od=OUT/'kb16_final'; od.mkdir(parents=True,exist_ok=True)
 (od/'README.md').write_text('# KB16 final outputs\n\n标准订单和财务草稿位于各不可覆盖回放目录；本索引对应 `evaluation/v7/kb16_validation_result.json`。财务文件均为本地测试草稿，没有真实导入或入账。\n',encoding='utf-8')
 report=f'''# V7-8 KB16 共享采购知识最终验证报告\n\n状态：**doing，未达到整体95% verified**。当前生产知识库是 KB16（93条概念规则、2条单位规则、1条受限表达结构规则，SHA `{kbsha}`）。运行链路从冻结聊天文本开始，expected、来源事件和历史决策只在运行冻结后由评测端读取。\n\n## 当前指标\n\n| 验证轨 | 模式 | 全量事件 | 实际自动 | 自动正确 | A | B | 结论 |\n|---|---|---:|---:|---:|---:|---:|---|\n| KB16 v1 | shared | 54 | 26 | 26 | 100% | 48.1481% | 业务处理正确率94.4444%；review/control不计自动B |\n| 语义已见回归 | shared | 84 | 72 | 72 | 100% | 85.7143% | 正常72/72；异常不计自动 |\n| 目录迁移回归 | shared | 324 | 306 | 306 | 100% | 94.4444% | 正常306/306；18条异常/控制独立保留 |\n| KB16 v2 外部概念 | shared | 96 | 3 | 2 | 66.6667% | 2.0833% | 8个外部概念未被当前知识库自动覆盖；首见保留8991不冒充未来新单 |\n\nA 使用实际 `matched + active` 事件作分母；误自动的 review/control 计入A错误，追加/改量/取消不冒充自动。B 只统计自动完成且全字段正确的事件 / 全量输入事件；正确转人工单独报告业务处理正确率，不计入B。C 因候选全集和异常语义未充分独立裁定保持 null/unknown。\n\n## 固定历史分母和原始回放\n\n三站聊天事件为159（松北大道53、星月42、学院路64），其中与人工表对齐155，当前目录可核人工SKU132。KB16 原始159回放输出完整53/42/64事件，三站财务机械错误0；合并财务159行复读错误0。历史随机变形回放不能作为新订单准确率。KB16历史固定SKU身份为80/132=60.6061%，覆盖155/159也单独保留在 `kb16_final_history_identity.json`；人工实配量、替代和旧价不进入运行端。\n\n## 异常与候选\n\n有限候选审计中，已见四概念36/36候选集合完整；fresh六类18条按类别分别记录，snow/bean/brand候选全集未知，brown_bag/brown_missing身份与数量安全通过，orange身份/数量通过但公司边界阻塞。未知金额保持空白，标准订单和财务草稿保留异常行。候选有限见证不等于真实语义全集，不能把C写成通过。\n\n## v2保留集边界\n\n每seed32条（24条件正常、4 review、4控制），8901/8902为开发，8991为首见保留；三seed共享表达池。牛心管“切段”等要求在当前目录没有切段规格证据，业务设计要求待核，不能为提高分数强行自动。\n\n## 工程与安全证据\n\n193项核心测试通过；评分器契约测试7/7通过；v1三模式9次运行、semantic/fresh/v2原文CLI、订单/财务复读、合并财务和八份original前后SHA均通过。所有产物在 `ordertcr/`，未连接真实订单系统、未上传、未正式入账。千问办公、WorkBuddy、真实新增订单尚未验证。\n\n下一轮优先级：补充不依赖历史样本的目录属性语义开发集，并把每个外部概念的目录依据、是否可自动和应转人工拆开；修复v2评测预期与业务约束的冲突后再讨论是否能提升B。\n'''
 (E/'kb16_report.md').write_text(report,encoding='utf-8')
 print(json.dumps({'status':'doing','kb_sha256':kbsha,'original_equal':original_equal},ensure_ascii=False))
if __name__=='__main__': main()
